function t(k) { const d = I18N[lang] || I18N.ar; return d[k] != null ? d[k] : (I18N.ar[k] != null ? I18N.ar[k] : k); }
function applyStaticText() {
  $$('[data-i18n]').forEach(e => { e.textContent = t(e.dataset.i18n); });
  $$('[data-i18n-ph]').forEach(e => { e.setAttribute('placeholder', t(e.dataset.i18nPh)); });
  const ti = document.querySelector('title');
  if (ti && ti.dataset.i18n) ti.textContent = t(ti.dataset.i18n);
}
function setLang(l) {
  lang = (l === 'fr' || l === 'en') ? l : 'ar';
  store.set('rbm_lang', lang);
  document.documentElement.lang = lang;
  document.documentElement.dir = lang === 'ar' ? 'rtl' : 'ltr';
  applyStaticText();
  renderChrome(document.body.dataset.page || '');
  if (typeof window.RBM_RERENDER === 'function') window.RBM_RERENDER();
  if (typeof window.RBM_CONV_REFRESH === 'function') window.RBM_CONV_REFRESH();
}
